// Generated by Cypress Author on 2026-10-02.
import { mountWorkspace, mockRefresh, task } from "../../support/tasks";

describe("Delete tasks", () => {
  beforeEach(() => {
    mountWorkspace([task()]);
    cy.get('[aria-label="Delete Buy groceries"]').click();
    cy.get("dialog[open]").should("be.visible").and("contain.text", "Buy groceries");
  });

  it("confirms deletion → removes the task and shows the empty state", () => {
    cy.intercept("DELETE", "/api/tasks/42", { statusCode: 204 }).as("deleteTask");
    mockRefresh([]);
    cy.contains("dialog button", "Delete task").click();
    cy.wait("@deleteTask").its("response.statusCode").should("equal", 204);
    cy.wait("@refreshTasks");
    cy.get("dialog").should("not.exist");
    cy.get('[role="status"]').should("have.text", "Task deleted.");
    cy.get('section[aria-label="Task list"] li').should("not.exist");
    cy.contains("Make room for your next idea").should("be.visible");
    cy.get("[data-task-create]").should("be.focused");
    cy.get("@deleteTask.all").should("have.length", 1);
  });

  it("fails to delete → retains the task and allows retry", () => {
    cy.intercept("DELETE", "/api/tasks/42", {
      statusCode: 500, body: { message: "Unable to delete task." },
    }).as("deleteTask");
    cy.contains("dialog button", "Delete task").click();
    cy.wait("@deleteTask");
    cy.get('dialog [role="alert"]').should("have.text", "Unable to delete task.");
    cy.contains("dialog button", "Delete task").should("be.enabled");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Buy groceries");
    cy.get('[role="status"]').should("not.exist");
  });

  it("cancels deletion → retains the task without a delete request", () => {
    cy.intercept("DELETE", "/api/tasks/42", { statusCode: 204 }).as("deleteTask");
    cy.contains("dialog button", "Cancel").should("be.focused").click();
    cy.get("dialog").should("not.exist");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Buy groceries");
    cy.get('[aria-label="Delete Buy groceries"]').should("be.focused");
    cy.get("@deleteTask.all").should("have.length", 0);
  });
});
